import json, sys

SRC = sys.argv[1]
OUT = sys.argv[2]

def as_text(v):
    if isinstance(v, str):
        return v
    return json.dumps(v, indent=2, ensure_ascii=False)

def trunc(s, n=6000):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"\n… [truncated {len(s)-n} chars]"

# map tool_use_id -> tool name for labeling results
names = {}
rows = []
with open(SRC) as f:
    for ln in f:
        ln = ln.strip()
        if not ln:
            continue
        d = json.loads(ln)
        if d.get("type") not in ("user", "assistant"):
            continue
        m = d.get("message")
        if not isinstance(m, dict):
            continue
        content = m.get("content")
        if isinstance(content, str):
            content = [{"type": "text", "text": content}]
        if not isinstance(content, list):
            continue
        rows.append((d.get("type"), d.get("timestamp", ""), content))
        for b in content:
            if isinstance(b, dict) and b.get("type") == "tool_use":
                names[b.get("id")] = b.get("name")

out = []
out.append("# CDS QA Session — Full Transcript\n")
out.append("Session `d288d712-675c-42a9-8308-85b03d458ed7` · project `cds` · branch `feat/t8-concept-definition-app`\n")
out.append("> QA task: add a residents need about predictable delivery windows via the cds MCP tools, verify, show findings.\n")
out.append("\n---\n")

turn = 0
for role, ts, content in rows:
    for b in content:
        if not isinstance(b, dict):
            continue
        t = b.get("type")
        if t == "text":
            txt = (b.get("text") or "").strip()
            if not txt:
                continue
            if role == "user":
                # skip pure system-reminder / tool noise; keep real user prompts
                out.append(f"\n## 🧑 User\n\n{txt}\n")
            else:
                out.append(f"\n### 🤖 Assistant\n\n{txt}\n")
        elif t == "thinking":
            think = (b.get("thinking") or "").strip()
            if think:
                out.append("\n<details><summary>💭 Reasoning</summary>\n\n" +
                           trunc(think) + "\n\n</details>\n")
        elif t == "tool_use":
            name = b.get("name", "?")
            inp = trunc(as_text(b.get("input", {})), 3000)
            out.append(f"\n**🔧 Tool call — `{name}`**\n\n```json\n{inp}\n```\n")
        elif t == "tool_result":
            name = names.get(b.get("tool_use_id"), "")
            c = b.get("content")
            if isinstance(c, list):
                c = "\n".join(x.get("text", as_text(x)) if isinstance(x, dict) else str(x) for x in c)
            out.append(f"\n**📤 Result** ({name})\n\n```\n{trunc(as_text(c), 4000)}\n```\n")

with open(OUT, "w") as f:
    f.write("\n".join(out))
print("wrote", OUT, "turns from", len(rows), "messages")

